// Turn the incoming request into a Gemini "generateContent" body.
const body = ($input.first().json.body) || {};
const topic = (body.content || body.topic || '').trim();
if (!topic) { throw new Error('Field "content" (the topic/instructions) is required.'); }

const nSlides = Number(body.n_slides) || 6;
const tone = body.tone || '';
const audience = body.audience || '';
const instructions = body.instructions || '';

const SYSTEM_PROMPT = "You are an expert presentation designer.\nReturn ONLY valid JSON (no markdown fences, no commentary) as {\"title\": string, \"slides\": [Slide, ...]}.\nEach Slide is one of these shapes:\n- {\"type\":\"title\",\"title\":string,\"subtitle\":string,\"image_query\":string}\n- {\"type\":\"section\",\"title\":string,\"subtitle\":string,\"image_query\":string}\n- {\"type\":\"content\",\"title\":string,\"bullets\":string[],\"notes\":string,\"image_query\":string(optional)}\n- {\"type\":\"stat\",\"title\":string,\"stats\":[{\"value\":string,\"label\":string}]}\n- {\"type\":\"quote\",\"quote\":string,\"attribution\":string(optional)}\n- {\"type\":\"closing\",\"title\":string,\"subtitle\":string,\"image_query\":string}\nRules:\n- Start with one \"title\" slide and end with one \"closing\" slide.\n- Use a VARIED mix: several \"content\" slides, at least one \"section\" divider, and where they fit, one \"stat\" slide and/or one \"quote\" slide. Do not make every slide a bullet list.\n- \"content\" bullets: 3-5 concise, parallel points (max ~12 words). Include brief \"notes\".\n- \"stat\": 1-3 entries; values are illustrative estimates (e.g. \"70%\", \"3x\"), not cited facts.\n- \"quote\": do NOT fabricate quotes from real, named people. Use an illustrative statement; omit attribution or attribute generically (e.g. \"Industry perspective\").\n- \"image_query\": a 2-4 word visual search term (e.g. \"electric vehicle highway\"). Add it to the title, section, and closing slides, and to 1-2 content slides that suit a photo. Omit it elsewhere.\n- Keep titles short and specific. No markdown, no emojis.";

const userLines = [
  'Create a presentation about: ' + topic,
  'Target roughly ' + nSlides + ' slides (including title and closing).',
];
if (tone) userLines.push('Tone: ' + tone + '.');
if (audience) userLines.push('Audience: ' + audience + '.');
if (instructions) userLines.push('Extra instructions: ' + instructions + '.');

const geminiBody = {
  systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
  contents: [{ role: 'user', parts: [{ text: userLines.join('\n') }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.7,
    // Disable model "thinking" for speed (flash-lite): ~4s vs ~8-10s.
    thinkingConfig: { thinkingBudget: 0 },
  },
};

return [{ json: { geminiBody } }];

// Extract and validate the deck JSON returned by Gemini.
const res = $input.first().json;
const raw = res && res.candidates && res.candidates[0]
  && res.candidates[0].content && res.candidates[0].content.parts
  && res.candidates[0].content.parts[0] && res.candidates[0].content.parts[0].text;
if (!raw) {
  throw new Error('No content returned by Gemini: ' + JSON.stringify(res).slice(0, 300));
}
// Defensive: strip accidental markdown fences before parsing.
const cleaned = String(raw).replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
let deck;
try { deck = JSON.parse(cleaned); }
catch (e) { throw new Error('Gemini did not return valid JSON deck.'); }
if (!deck.title || !Array.isArray(deck.slides) || deck.slides.length === 0) {
  throw new Error('Deck is missing a title or slides.');
}
// Derive the visual theme from the requested tone (tones map 1:1 to themes).
const VALID_THEMES = ['professional', 'casual', 'academic', 'persuasive', 'inspirational'];
let tone = '';
try { tone = (($('Webhook').first().json.body) || {}).tone || ''; } catch (e) {}
deck.theme = VALID_THEMES.indexOf(tone) !== -1 ? tone : 'professional';
return [{ json: { deck } }];
